import {
  Body,
  Controller,
  Get,
  HttpStatus,
  Post,
  Query,
  Res,
} from '@nestjs/common';
import {
  ApiExcludeEndpoint,
  ApiInternalServerErrorResponse,
  ApiNotFoundResponse,
  ApiOkResponse,
  ApiOperation,
  ApiTags,
} from '@nestjs/swagger';
import { Response } from 'express';
import { CauseFamilyAssignService } from './cause-family-assign.service';
import { CauseFamilyAssignParametersDTO } from './dto/family-parameters.dto';
import { ResponseFamilyDTO } from './dto/family-response.dto';
import { CauseFamilyAssign } from './entities/cause-family-assign.entity';
import { AppLogger } from '@/common/logger/app-logger';

@ApiTags('Cause Family Assign')
@Controller('cause-family-assign')
export class CauseFamilyAssignController {
  private readonly logger = new AppLogger(CauseFamilyAssignService.name);

  public constructor(
    private readonly causeFamilyAssignService: CauseFamilyAssignService,
  ) {}

  @ApiExcludeEndpoint()
  @Post('create')
  public async create(
    @Body() causeFamilyAssign: CauseFamilyAssign,
    @Res() response: Response,
  ): Promise<Response> {
    try {
      const result =
        await this.causeFamilyAssignService.create(causeFamilyAssign);

      return response.json(result);
    } catch (error) {
      this.logger.error(`error in creating cause family assign${error}`);
      return response.status(HttpStatus.INTERNAL_SERVER_ERROR).json({
        message: 'Internal Server Error',
        status: HttpStatus.INTERNAL_SERVER_ERROR,
      });
    }
  }

  @ApiExcludeEndpoint()
  @Get('all')
  public findAll(): Promise<Array<CauseFamilyAssign>> {
    return this.causeFamilyAssignService.findAll();
  }

  @ApiOperation({
    description:
      'This endpoint allows you to retrieve list of family by plant and cause, both the plant and cause parameters are mandatory.',
    summary: 'Get family by plant and by cause',
  })
  @ApiOkResponse({
    description: 'FamilyList ',
    type: ResponseFamilyDTO,
  })
  @ApiNotFoundResponse({
    description: 'Family list Not Found.',
    status: 404,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  @Get('getFamilyByPlantAndCause')
  public async getListOfFamilyByPlantAndByCause(
    @Query() query: CauseFamilyAssignParametersDTO,
    @Res() response: Response,
  ): Promise<Response> {
    const { plant, cause } = query;
    const result =
      await this.causeFamilyAssignService.findListOfFamilyByPlantAndByCause(
        plant,
        cause,
      );
    if (result !== undefined) {
      return response.json(result);
    }
    return response
      .status(HttpStatus.NOT_FOUND)
      .json({ message: 'Family list Not Found', status: HttpStatus.NOT_FOUND });
  }
}

