import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class CauseFamilyAssignService {
  private readonly logger = new AppLogger(CauseFamilyAssignService.name);

  public constructor(
    // Inject the repository for CauseFamilyAssign entity
    @InjectRepository(CauseFamilyAssign)
    private readonly causeFamilyAssignRepo: Repository<CauseFamilyAssign>,
  ) {}

  public async create(causeFamilyAssign: CauseFamilyAssign): Promise<void> {
    await this.causeFamilyAssignRepo.insert(causeFamilyAssign);
  }

  public findAll(): Promise<Array<CauseFamilyAssign>> {
    return this.causeFamilyAssignRepo.find();
  }

  public async findListOfFamilyByPlantAndByCause(
    plant: number,
    cause: string,
  ): Promise<Array<ResponseFamilyDTO>> {
    try {
      const family = await this.causeFamilyAssignRepo
        .createQueryBuilder('cause_family_assign')
        .select('cause_family_assign.family', 'family')
        .where('cause_family_assign.plant =:plant', { plant })
        .andWhere('cause_family_assign.cause =:cause', { cause })
        .getRawMany();
      if (family) {
        return family;
      }
      return [];
    } catch (error) {
      this.logger.error(error);
      return [];
    }
  }
}

