import { Injectable } from '@nestjs/common';
import { ContainerCleanupService } from '../container/container-cleanup.service';
import { ContainerJobOptionsDto } from '../container/dto/container-job-options.dto';
import { DowntimeTicketCleanupService } from '../down-time-ticket/down-time-ticket-cleanup.service';
import { DowntimeTicketJobOptionsDto } from '../down-time-ticket/dto/down-time-ticket-job-options.dto';
import { CleanUpOptionsDto } from './dto/clean-up-options.dto';
import { CleanUpResponseDto } from './dto/clean-up-response.dto';
import { CleanUpResultDto } from './dto/clean-up-result.dto';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class CleanUpService {
  private readonly logger = new AppLogger(CleanUpService.name);

  public constructor(
    private readonly containerCleanupService: ContainerCleanupService,
    private readonly downtimeTicketCleanupService: DowntimeTicketCleanupService,
  ) {}

  /**
   * Orchestrates cleanup procedures to run in parallel for all plants
   * @param options - Cleanup options containing containerOptions and downtimeTicketOptions
   * @returns CleanUpResponseDto with results from all procedures
   */
  public async runCleanupForAllPlants(
    options: ContainerJobOptionsDto,
  ): Promise<CleanUpResponseDto> {
    const startedAt = new Date();
    const startTime = Date.now();

    this.logger.log(
      'Starting parallel execution of cleanup procedures for all plants',
    );

    // Run all cleanup procedures in parallel
    const results = await Promise.allSettled([
      this.runContainerCleanup(options),
      this.runDowntimeTicketCleanup(options),
    ]);

    const completedAt = new Date();
    const totalDurationMs = Date.now() - startTime;

    // Process results
    const cleanupResults: Array<CleanUpResultDto> = results.map(
      (result, index) => {
        const procedureNames = ['Container Cleanup', 'Downtime Ticket Cleanup'];

        if (result.status === 'fulfilled') {
          return result.value;
        }
        this.logger.error(`${procedureNames[index]} failed: ${result.reason}`);
        return {
          durationMs: 0,
          error: result.reason?.message || 'Unknown error',
          procedureName: procedureNames[index],
          success: false,
        };
      },
    );

    const overallSuccess = cleanupResults.every((result) => result.success);

    this.logger.log(
      `All cleanup procedures completed. Overall success: ${overallSuccess}. Total duration: ${totalDurationMs}ms`,
    );

    return {
      completedAt,
      overallSuccess,
      results: cleanupResults,
      startedAt,
      totalDurationMs,
    };
  }

  /**
   * Runs container cleanup for all plants and returns a result object
   * @param options - Container cleanup options
   * @returns CleanUpResultDto with result information
   */
  private async runContainerCleanup(
    options?: ContainerJobOptionsDto,
  ): Promise<CleanUpResultDto> {
    const startTime = Date.now();
    try {
      this.logger.log('Starting Container cleanup for all plants');
      await this.containerCleanupService.runDeleteContainerProcedureForAllPlants(
        options,
      );
      const durationMs = Date.now() - startTime;

      return {
        durationMs,
        procedureName: 'Container Cleanup',
        success: true,
      };
    } catch (error) {
      const durationMs = Date.now() - startTime;
      const errorMessage = error?.message || 'Unknown error';

      return {
        durationMs,
        error: errorMessage,
        procedureName: 'Container Cleanup',
        success: false,
      };
    }
  }

  /**
   * Runs downtime ticket cleanup for all plants and returns a result object
   * @param options - Downtime ticket cleanup options
   * @returns CleanUpResultDto with result information
   */
  private async runDowntimeTicketCleanup(
    options?: DowntimeTicketJobOptionsDto,
  ): Promise<CleanUpResultDto> {
    const startTime = Date.now();
    try {
      this.logger.log('Starting Downtime Ticket cleanup for all plants');
      await this.downtimeTicketCleanupService.runDeleteDowntimeTicketProcedureForAllPlants(
        options,
      );
      const durationMs = Date.now() - startTime;

      return {
        durationMs,
        procedureName: 'Downtime Ticket Cleanup',
        success: true,
      };
    } catch (error) {
      const durationMs = Date.now() - startTime;
      const errorMessage = error?.message || 'Unknown error';

      return {
        durationMs,
        error: errorMessage,
        procedureName: 'Downtime Ticket Cleanup',
        success: false,
      };
    }
  }
}

