        .select('container.container_id', 'containerId')
        .addSelect('container.create_on', 'createOn')
        .addSelect('container.picking_order_id', 'pickingOrderId')
        .addSelect('container.book_date', 'bookDate')
        .addSelect(
          'container.current_storage_location',
          'currentStorageLocation',
        )
        .where('container.plant = :plant', { plant })
        .andWhere('container.picking_order_id  IN(:...pickingOrderList) ', {
          pickingOrderList,
        })
        .andWhere('container.pack_type = :packType', { packType: 'UM' })
        .getRawMany();
      const result: Record<string, ContainerPickingOrderListResponseDTO> = {};
      for (const container of containers) {
