        .createQueryBuilder('container')
        .select('container.picking_order_id', 'pickingOrderId')
        .addSelect('container.book_date', 'bookDate')
        .where('container.plant = :plant', { plant })
        .andWhere('container.picking_order_id  IN(:...pickingOrderList) ', {
          pickingOrderList,
        })
        .getRawMany();
      const result: Record<string, Date> = {};
      for (const container of containers) {
        result[container.pickingOrderId] = container.bookDate;
      }
      return result;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve container [plant: ${plant}]: ${error.message}`,
      );

      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException('Failed to retrieve container');
      }
      throw error;
    }
