          'containerId',
          'status',
          'unit',
          'currentStorageLocation',
          'material',
          'quantity',
          'bookDate',
          'createOn',
          'createBy',
          'pickingOrderId',
          'blocked',
          'packType',
          'externalHu',
          'workcenter',
          'packagingMaterial',
          'type',
          'printed',
        ],
        where: {
          containerId: In(containerIdList),
          plant,
        },
      });

      const result: Record<string, ContainerByIdResponseDto> = {};

      for (const container of containers) {
        const { containerId, ...data } = container;
        result[containerId] = data;
      }

      return result;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve container [plant: ${plant}]: ${error.message}`,
      );

      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException('Failed to retrieve container');
      }
      throw error;
    }
  }
