@Injectable()
export class DownTimeCauseService {
  /**
   * Safely convert a value to string without relying on default Object stringification.
   * Returns empty string for null/undefined.
   * @param value - value to convert to string
   * @returns a string representation of the provided value ('' for null/undefined or on stringify failure)
   */

  private static getStatus(
    causeId: string,
    causeMap: Map<string, Cause>,
  ): string {
    const cause = causeMap.get(causeId);

    if (cause && cause.status === 'ACTIVATED') return 'ACTIVE';
    if (cause && cause.status === 'DESACTIVATED') return 'INACTIVE';
    let parentId = cause ? cause.parentCause : '';
    while (parentId) {
      const parent = causeMap.get(parentId);
      if (!parent) break;
      if (parent.status === 'DESACTIVATED') return 'INACTIVE';
      if (parent.status === 'ACTIVATED') {
        parentId = parent.parentCause;
      }

      if (!parent.status) break;
    }

    return 'ACTIVE';
  }

  private readonly logger = new AppLogger();

  private readonly nestLogger = new Logger(DownTimeCauseService.name);

  public constructor(
    // Inject the repository for DownTimeCause entity
    @InjectRepository(DownTimeCause)
    private readonly downTimeCauseRepo: Repository<DownTimeCause>,
    @InjectRepository(ResourceFamilyAssign)
    private readonly resourceFamilyAssignRepo: Repository<ResourceFamilyAssign>,
    @InjectRepository(CauseFamilyAssign)
    private readonly causeFamilyAssignRepo: Repository<CauseFamilyAssign>,
    @InjectRepository(DownTimeCauseTranslation)
    private readonly downTimeCauseTranslationRepo: Repository<DownTimeCauseTranslation>,
  ) {}

  /**
   * Helper to handle level '2' filtering for findDownTimeCauseWithLevel.
   * Extracted to reduce cognitive complexity of the main method.
   * @param queryBuilder - TypeORM query builder pre-configured for down_time_cause
   * @param plant - plant identifier
   * @param resource - resource identifier (optional)
   * @param causeGlobal - cause global filter (optional)
   * @param parentCause - parent cause filter (optional)
   * @returns Filtered list of causes for level 2
   */
  private async filterLevel2Causes(
    queryBuilder: unknown,
    plant: number,
    resource?: string,
    causeGlobal?: number,
    parentCause?: string,
  ): Promise<Array<ResponseDownTimeCauseDTO>> {
    const qb = queryBuilder as {
      andWhere: (...arguments_: Array<unknown>) => unknown;
      getRawMany: () => Promise<Array<Record<string, unknown>>>;
    };
    // Preserve the original filtering for causeGlobal and parentCause
    if (causeGlobal !== undefined) {
      qb.andWhere('down_time_cause.cause_global = :causeGlobal', {
        causeGlobal,
      });
    }

    if (parentCause !== undefined) {
      qb.andWhere('down_time_cause.parent_cause = :parentCause', {
        parentCause,
      });
    }

    // Step 1: Get causes for level 2
    const causes: Array<Record<string, unknown>> = await qb.getRawMany();
    const causeIds: Array<string> = causes.map((c: Record<string, unknown>) =>
      safeToString(c['cause']),
    );

    // Step 2: Fetch resource families
    let resourceFamilyList: Array<string> = [];
    if (resource) {
      const resourceFamilies: Array<Record<string, unknown>> =
        await this.resourceFamilyAssignRepo
          .createQueryBuilder('resource_family_assign')
          .select('resource_family_assign.family', 'family')
          .where('resource_family_assign.plant = :plant', { plant })
          .andWhere('resource_family_assign.resource = :resource', { resource })
          .getRawMany();

      resourceFamilyList = resourceFamilies.map((rf: Record<string, unknown>) =>
        safeToString(rf['family']),
      );
    }

    // Step 3: Fetch all families associated with the causes in one query
    const causeFamilies: Array<Record<string, unknown>> =
      await this.causeFamilyAssignRepo
        .createQueryBuilder('cause_family_assign')
        .select(['cause_family_assign.cause', 'cause_family_assign.family'])
        .where('cause_family_assign.plant = :plant', { plant })
        .andWhere('cause_family_assign.cause IN (:...causeIds)', { causeIds })
        .getRawMany();

    // Step 4: Create a mapping of causes to families
    const causeFamilyMap: Record<string, Array<string>> = {};
    for (const cf of causeFamilies) {
      const cause = cf['cause_family_assign_cause']
        ? safeToString(cf['cause_family_assign_cause'])
        : '';
      const family = cf['cause_family_assign_family']
        ? safeToString(cf['cause_family_assign_family'])
        : '';

      if (cause) {
        if (!causeFamilyMap[cause]) {
          causeFamilyMap[cause] = [];
        }
        causeFamilyMap[cause].push(family);
      } else {
        this.logger.warn(`Skipping cause with no cause ID: ${cause}`);
      }
    }

    // Step 5: If no resource families are provided or no matches are found, return all causes
    if (
      resourceFamilyList.length === 0 ||
      Object.keys(causeFamilyMap).length === 0
    ) {
      // Filter out causes that have families assigned if no resource family is found
      const causesWithNoFamilies = causes.filter(
        (c: Record<string, unknown>) => {
          const causeKey = safeToString(c['cause']);
          const causeFamiliesArray = causeFamilyMap[causeKey] || [];
          return causeFamiliesArray.length === 0; // Causes with no family assigned
        },
      );

      return causesWithNoFamilies.map((r) => mapRawToResponseDTO(r));
    }

    // Step 6: Filter matching causes based on family relationships
    const matchingCauses = causes.filter((c: Record<string, unknown>) => {
      const causeKey = safeToString(c['cause']);
      const causeFamiliesArray = causeFamilyMap[causeKey] || [];

      // Match causes without families if no resource families are provided
      if (resourceFamilyList.length === 0 && causeFamiliesArray.length === 0) {
        return true;
      }
      // Match causes with overlapping families
      return causeFamiliesArray.some((family) =>
        resourceFamilyList.includes(family),
      );
    });

    // Step 7: If no matching causes, return all causes
    if (matchingCauses.length === 0) {
      return causes.map((r) => mapRawToResponseDTO(r));
    }

    return matchingCauses.map((r) => mapRawToResponseDTO(r));
  }

