  public async addCauseDescriptionTranslation(payload: {
    plant: number;
    cause: string;
    targetLanguage: string;
    translatedDesc: string;
    isManual?: boolean;
  }): Promise<void> {
    const lang = payload.targetLanguage
      ? payload.targetLanguage.toLowerCase()
      : undefined;

    try {
      const existing = await this.downTimeCauseTranslationRepo.findOne({
        where: {
          plant: payload.plant,
          cause: payload.cause,
          targetLanguage: lang,
        },
      });

      if (existing) {
        existing.translatedDesc = payload.translatedDesc;
        existing.isManual = payload.isManual === true;
        await this.downTimeCauseTranslationRepo.save(existing);
      } else {
        await this.downTimeCauseTranslationRepo.insert({
          cause: payload.cause,
          isManual: payload.isManual === true,
          plant: payload.plant,
          targetLanguage: lang,
          translatedDesc: payload.translatedDesc,
        } as DownTimeCauseTranslation);
      }
    } catch (error) {
      this.logger.error(`Failed to save translation: ${error}`);
      throw new InternalServerErrorException('Failed to save translation');
    }
  }

  /**
   * Bulk add or update cause description translations.
   * Performs upserts inside a transaction to ensure atomicity.
   * @param items Array of translation items to add or update
   * @returns counts of added and updated records
   */
  public async addBulkCauseDescriptionTranslations(
    items: Array<{
      plant: number;
      cause: string;
      lang: string;
      translatedDesc: string;
      isManual?: boolean;
    }>,
  ): Promise<{ added: number; updated: number }> {
    if (!Array.isArray(items) || items.length === 0) {
      throw new BadRequestException(
        'Items array is required and must not be empty',
      );
    }

    // Basic validation: ensure required fields are present for every item
    for (const [index, it] of items.entries()) {
      if (!it || typeof it !== 'object') {
        throw new BadRequestException(`Item at index ${index} is invalid`);
      }
      if (!Number.isInteger(it.plant)) {
        throw new BadRequestException(
          `Item at index ${index} has invalid or missing plant`,
        );
      }
      if (!it.cause || typeof it.cause !== 'string') {
        throw new BadRequestException(
          `Item at index ${index} has invalid or missing cause`,
        );
      }
      if (!it.lang || typeof it.lang !== 'string') {
        throw new BadRequestException(
          `Item at index ${index} has invalid or missing lang`,
        );
      }
      if (
        it.translatedDesc === undefined ||
        it.translatedDesc === null ||
        typeof it.translatedDesc !== 'string'
      ) {
        throw new BadRequestException(
          `Item at index ${index} has invalid or missing translatedDesc`,
        );
      }
    }

    let added = 0;
    let updated = 0;

    try {
      // Verify that all referenced causes exist for their plants before performing any writes
      const plantToCauses: Map<number, Set<string>> = new Map();
      for (const it of items) {
        const plantSet = plantToCauses.get(it.plant) ?? new Set<string>();
        plantSet.add(it.cause);
        plantToCauses.set(it.plant, plantSet);
      }

      // Batch-check referenced causes for all plants to avoid awaiting inside a loop
      const allPlants = [...plantToCauses.keys()];
      const allCauses = [
        ...new Set([...plantToCauses.values()].flatMap((s) => [...s])),
      ];

      const foundCauses = await this.downTimeCauseRepo.find({
        where: { plant: In(allPlants), cause: In(allCauses) },
        select: ['plant', 'cause'],
      });

      const foundSet = new Set(
        foundCauses.map((f) => `${f.plant}::${f.cause}`),
      );
      const missingReport: Array<string> = [];

      for (const [plant, causesSet] of plantToCauses.entries()) {
        const missing = [...causesSet].filter(
          (c) => !foundSet.has(`${plant}::${c}`),
        );
        if (missing.length > 0) {
          missingReport.push(`plant ${plant}: ${missing.join(',')}`);
        }
      }

      if (missingReport.length > 0) {
        throw new BadRequestException(
          `Referenced causes not found: ${missingReport.join('; ')}`,
        );
      }

      await this.downTimeCauseTranslationRepo.manager.transaction(
        async (manager) => {
          // First handle existing rows: fetch all translations matching the provided keys
          const keys = items.map((it) => ({
            plant: it.plant,
            cause: it.cause,
            lang: it.lang.toLowerCase(),
          }));
          const uniqueTargets = new Map<
            string,
            { plant: number; cause: string; lang: string }
          >();
          for (const k of keys) {
            uniqueTargets.set(`${k.plant}::${k.cause}::${k.lang}`, k);
          }

          const whereInserts = [...uniqueTargets.values()].map((u) => ({
            plant: u.plant,
            cause: u.cause,
            targetLanguage: u.lang,
          }));

          // Fetch existing translations in one query (use repository.find with a single options arg)
          const existingRows = await manager
            .getRepository(DownTimeCauseTranslation)
            .find({
              where: whereInserts,
            });

          const existingMap = new Map<string, DownTimeCauseTranslation>();
          for (const row of existingRows) {
            existingMap.set(
              `${row.plant}::${row.cause}::${row.targetLanguage}`,
              row,
            );
          }

          const inserts: Array<Promise<InsertResult>> = [];
          const saves: Array<Promise<DownTimeCauseTranslation>> = [];

          for (const it of items) {
            const lang = it.lang ? it.lang.toLowerCase() : undefined;
            if (!lang) throw new BadRequestException('Invalid language');

            const key = `${it.plant}::${it.cause}::${lang}`;
            const existing = existingMap.get(key);

            if (existing) {
              // Only update when there is an actual change to translatedDesc or isManual
              const existingDesc = existing.translatedDesc ?? null;
              const incomingDesc = it.translatedDesc ?? null;
              const existingManual = existing.isManual;
              const incomingManual = it.isManual === true;

              const descChanged = existingDesc !== incomingDesc;
              const manualChanged = existingManual !== incomingManual;

              if (descChanged || manualChanged) {
                existing.translatedDesc = it.translatedDesc;
                existing.isManual = incomingManual;
                saves.push(manager.save(existing));
                updated += 1;
              } else {
                // Nothing changed — skip saving and do not increment counts
              }
            } else {
              // Use insert to avoid loading relations; collect promises
              inserts.push(
                manager.insert(DownTimeCauseTranslation, {
                  cause: it.cause,
                  isManual: it.isManual === true,
                  plant: it.plant,
                  targetLanguage: lang,
                  translatedDesc: it.translatedDesc,
                } as DownTimeCauseTranslation),
              );
              added += 1;
            }
          }

          // Run all DB operations in parallel within the transaction
          await Promise.all([...inserts, ...saves]);
        },
      );
    } catch (error) {
      this.logger.error(`Failed to save bulk translations: ${error}`);
      // Any error will rollback the transaction and nothing will be persisted
      throw new InternalServerErrorException(
        'Failed to save bulk translations',
      );
    }

    return { added, updated };
  }

