  public async findAll(
    plant: string,
    resource: string,
    search?: string,
  ): Promise<Array<CauseHierarchyDTO>> {
    // Build the query to fetch distinct causes
    const queryBuilder = this.downTimeCauseRepo
      .createQueryBuilder('down_time_cause')
      .select([
        'DISTINCT down_time_cause.cause AS cause',
        'down_time_cause.plant AS plant',
        'down_time_cause.cause_global AS causeGlobal',
        'down_time_cause.cause_desc AS causeDesc',
        'down_time_cause.status AS status',
        'down_time_cause.parent_cause AS parentCause',
      ])
      .leftJoin(
        'cause_family_assign',
        'cause_family',
        'cause_family.plant = down_time_cause.plant AND cause_family.cause = down_time_cause.cause',
      )
      .leftJoin(
        'resource_family_assign',
        'resource_family',
        'down_time_cause.plant = resource_family.plant AND resource_family.resource = :resource',
        { resource },
      )
      .where('down_time_cause.plant = :plant', { plant })
      .andWhere('down_time_cause.cause != :excludedCause', {
        excludedCause: '6',
      })
      .andWhere('down_time_cause.status = :status', { status: 'ACTIVATED' });

    // Add search filter if provided
    if (search) {
      queryBuilder.andWhere(
        '((LOWER(down_time_cause.cause_desc) LIKE LOWER(:search) OR down_time_cause.cause LIKE LOWER(:search)))',
        {
          search: `%${search}%`,
        },
      );
    }
    // Fetch distinct causes from the database
    const causes: Array<Record<string, unknown>> =
      await queryBuilder.getRawMany();
    // Prepare promises for level1, level2, and level3 data
    const promises: Array<Promise<CauseHierarchyDTO>> = causes.map(
      async (cause: Record<string, unknown>) => {
        // Extract typed values from raw record
        const causeDesc: string = safeToString(
          cause['causeDesc'] ??
            cause['cause_desc'] ??
            cause['down_time_cause_cause_desc'],
        );
        const causeGlobalRaw = cause['causeGlobal'] ?? cause['cause_global'];
        const causeGlobal = Number(causeGlobalRaw ?? 0);
        const parentCause: string = safeToString(
          cause['parentCause'] ?? cause['parent_cause'],
        );
        const causeCode: string = safeToString(cause['cause']);
        let exactSearch = false;
        if (causeCode === search || causeDesc === search) {
          exactSearch = true;
        }
        let level1 = '';
        let level2 = '';
        let level3 = '';
        const level1Code = String(causeGlobal);
        let level2Code = parentCause;
        let level3Code = '';

        if (parentCause === String(causeGlobal)) {
          level1 = await this.getCauseDescByCauseX(parentCause, plant);
          level2 = await this.getCauseDescByCauseX(causeCode, plant);
          level2Code = causeCode;
          const causeXFound = await this.getCauseDescByParentCauseX(
            causeCode,
            plant,
          );
          if (
            causeXFound &&
            causeXFound !== 'Unknown' &&
            typeof causeXFound != 'string'
          ) {
            level3 = causeXFound.causeDesc;
            level3Code = causeXFound.cause;
          }
        } else {
          level1 = await this.getCauseDescByGlobalCause(causeGlobal, plant);
          level2 = await this.getCauseDescByCauseX(parentCause, plant);
          level3 = causeDesc || '';
          level3Code = causeCode;
        }

        const result: CauseHierarchyDTO = {
          level1,
          level1Code: Number(level1Code),
          level2,
          level2Code,
        };
        result.exactSearch = exactSearch;
        if (level3 && level3 !== level2 && level3 !== 'Unknown') {
          result.level3 = level3;
          result.level3Code = level3Code;
        }

        return result;
      },
    );

    const results: Array<CauseHierarchyDTO> = await Promise.all(promises);

    // Use a Map to ensure uniqueness based on a stringified key
    const uniqueResults: Array<CauseHierarchyDTO> = [
      ...new Map(
        results.map((item: CauseHierarchyDTO) => [
          `${item.level1}-${item.level2}-${item.level3 ?? ''}`, // Unique key
          item,
        ]),
      ).values(),
    ];

    return uniqueResults;
  }

