  public async findDownTimeCauseWithLevel(
    plant: number,
    level?: string,
    resource?: string,
    causeGlobal?: number,
    parentCause?: string,
  ): Promise<Array<ResponseDownTimeCauseDTO>> {
    try {
      const queryBuilder = this.downTimeCauseRepo
        .createQueryBuilder('down_time_cause')
        .select('down_time_cause.plant', 'plant')
        .addSelect('down_time_cause.cause', 'cause')
        .addSelect('down_time_cause.parent_cause', 'parent cause')
        .addSelect('down_time_cause.cause_desc', 'cause desc')
        .addSelect('down_time_cause.cause_global', 'cause global')
        .addSelect('down_time_cause.status', 'status')
        .where('down_time_cause.plant =:plant', { plant })
        .andWhere('down_time_cause.status =:status', { status: 'ACTIVATED' })
        .andWhere('down_time_cause.cause !=:cause', { cause: '6' });

      if (level === '1') {
        queryBuilder.andWhere('down_time_cause.parent_cause IS NULL');
        const causes = queryBuilder.getRawMany();
        return await causes;
      }

      if (level === '2') {
        // Preserve the original filtering for causeGlobal and parentCause
        if (causeGlobal !== undefined) {
          queryBuilder.andWhere('down_time_cause.cause_global = :causeGlobal', {
            causeGlobal,
          });
        }

        if (parentCause !== undefined) {
          queryBuilder.andWhere('down_time_cause.parent_cause = :parentCause', {
            parentCause,
          });
        }

        // Step 1: Get causes for level 2
        const causes = await queryBuilder.getRawMany();
        const causeIds = causes.map((cause) => cause.cause);

        // Step 2: Fetch resource families
        const resourceFamilies = await this.resourceFamilyAssignRepo
          .createQueryBuilder('resource_family_assign')
          .select('resource_family_assign.family', 'family')
          .where('resource_family_assign.plant = :plant', { plant })
          .andWhere('resource_family_assign.resource = :resource', { resource })
          .getRawMany();

        const resourceFamilyList = resourceFamilies.map((rf) => rf.family);

        // Step 3: Fetch all families associated with the causes in one query
        const causeFamilies = await this.causeFamilyAssignRepo
          .createQueryBuilder('cause_family_assign')
          .select(['cause_family_assign.cause', 'cause_family_assign.family'])
          .where('cause_family_assign.plant = :plant', { plant })
          .andWhere('cause_family_assign.cause IN (:...causeIds)', { causeIds })
          .getRawMany();

        // Step 4: Create a mapping of causes to families
        const causeFamilyMap: Record<string, Array<string>> = {};
        for (const {
          cause_family_assign_cause: cause,
          cause_family_assign_family: family,
        } of causeFamilies) {
          if (!cause) {
            this.logger.warn(`Skipping cause with no cause ID: ${cause}`);
          }
          if (!causeFamilyMap[cause]) {
            causeFamilyMap[cause] = [];
          }
          causeFamilyMap[cause].push(family);
        }

        // Step 5: If no resource families are provided or no matches are found, return all causes
        if (
          resourceFamilyList.length === 0 ||
          Object.keys(causeFamilyMap).length === 0
        ) {
          // Filter out causes that have families assigned if no resource family is found
          const causesWithNoFamilies = causes.filter((cause) => {
            const causeFamiliesArray = causeFamilyMap[cause.cause] || [];
            return causeFamiliesArray.length === 0; // Causes with no family assigned
          });
          return causesWithNoFamilies;
        }

        // Step 6: Filter matching causes based on family relationships
        const matchingCauses = causes.filter((cause) => {
          const causeFamiliesArray = causeFamilyMap[cause.cause] || [];

          // Match causes without families if no resource families are provided
          if (
            resourceFamilyList.length === 0 &&
            causeFamiliesArray.length === 0
          ) {
            return true;
          }

          // Match causes with overlapping families
          return causeFamiliesArray.some((family) =>
            resourceFamilyList.includes(family),
          );
        });

        // Step 7: If no matching causes, return all causes
        if (matchingCauses.length === 0) {
          return causes;
        }

        return matchingCauses;
      }

      if (level === '3') {
        if (causeGlobal !== undefined) {
          queryBuilder.andWhere('down_time_cause.cause_global =:causeGlobal', {
            causeGlobal,
          });
        }

        if (parentCause !== undefined) {
          queryBuilder.andWhere('down_time_cause.parent_cause = :parentCause', {
            parentCause,
          });
        }

        const causes = queryBuilder.getRawMany();
        return await causes;
      }

      return [];
    } catch (error) {
      this.logger.error(error);
      return [];
    }
  }

  public async findChanges(
    plant: number,
    lastTimestamp: Date,
  ): Promise<Array<CauseHierarchy>> {
    try {
      const found = await this.downTimeCauseRepo.find({
        select: ['cause'],
        where: [
          { createdAt: MoreThanOrEqual(lastTimestamp), plant },
          { plant, updatedAt: MoreThanOrEqual(lastTimestamp) },
        ],
      });
      const downTimeCauseIds: Array<string> = found.map(
        (result: DownTimeCause) => result.cause,
      );
      if (downTimeCauseIds.length === 0) {
        throw new NotFoundException(
          `Causes changes not found [plant: ${plant}, lastTimestamp: ${lastTimestamp}]`,
        );
      }
      const causeHierarchy = await this.determineCauseLevels(
        downTimeCauseIds,
        plant,
      );
      return causeHierarchy;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve Causes changes [plant: ${plant}, lastTimestamp: ${lastTimestamp}]: ${error.message}`,
      );

      // Wrap and rethrow unexpected errors
      if (!(error instanceof NotFoundException)) {
        throw new InternalServerErrorException(
          'Failed to retrieve Causes changes',
        );
      }
      throw error;
    }
  }

  public async getFamiliesByCausesAndPlant(
    plant: number,
    causes: Array<string>,
  ): Promise<Array<GetFamiliesByCausesResponseDTO>> {
    const causeFamilies: Array<CauseFamilyAssign> =
      await this.causeFamilyAssignRepo
        .createQueryBuilder('cause_family_assign')
        .select(['cause_family_assign.cause', 'cause_family_assign.family'])
        .where('cause_family_assign.plant = :plant', { plant })
        .andWhere('cause_family_assign.cause IN (:...causes)', { causes })
        .getMany();

    // Extract only the causes that exist in the given plant
    const validCauses: Set<string> = new Set(
      causeFamilies.map((cfa: CauseFamilyAssign) => cfa.cause),
    );

    const groupedFamilies: Array<GetFamiliesByCausesResponseDTO> = [
      ...validCauses,
    ].map((cause: string) => ({
      cause,
      families: causeFamilies
        .filter((cfa: CauseFamilyAssign) => cfa.cause === cause)
        .map((cfa: CauseFamilyAssign) => cfa.family),
    }));

    return groupedFamilies;
  }

  private async getCauseDescription(causeId: string): Promise<string> {
    const cause = await this.downTimeCauseRepo.findOne({
      select: ['causeDesc'], // Only fetch causeDesc for efficiency
      where: { cause: causeId },
    });

    return cause?.causeDesc ?? 'Unknown Cause';
  }

  public async determineCauseLevels(
    causes: Array<string>,
    plant: number,
  ): Promise<Array<CauseHierarchy>> {
    // Fetch cause details from downTimeCauseRepo
    const results = await this.downTimeCauseRepo.find({
      where: { cause: In(causes), plant },
    });

    // Fetch families for causes
    const causeFamilies = await this.getFamiliesByCausesAndPlant(plant, causes);
    const familyMap = new Map<string, Array<string>>(); // Map of cause -> families

    for (const { cause, families } of causeFamilies) {
      familyMap.set(cause, families);
    }

    // Create a Map for quick lookups
    const causeMap = new Map<string, Cause>();
    for (const cause of results) {
      causeMap.set(cause.cause, {
        cause: cause.cause,
        causeDesc: cause.causeDesc,
        causeGlobal: String(cause.causeGlobal),
        family: familyMap.get(cause.cause) ?? [],
        finalStatus: cause.status,
        level: null,
        parentCause: cause.parentCause,
        status: cause.status,
      });
    }

    // Assign levels based on causeGlobal and parentCause
    for (const cause of causeMap.values()) {
      if (cause.parentCause && cause.causeGlobal) {
        cause.level =
          String(cause.parentCause).trim() === String(cause.causeGlobal).trim()
            ? 2
            : 3;
      } else {
        cause.level = 1; // Default Level 1 (no parent/global cause)
      }

      // Determine final status
      cause.finalStatus = DownTimeCauseService.getStatus(cause.cause, causeMap);
    }

    // Build and return the hierarchy
    return Promise.all(
      [...causeMap.values()].map(async (cause) => {
        let level1Description = '';
        let level1Id = '';
        let level2Description = '';
        let level2Id = '';
        let level3Description = '';
        let level3Id = '';

        if (cause.level === 2) {
          level1Id = cause.parentCause ?? '';
          level1Description = await this.getCauseDescription(level1Id);
          level2Id = cause.cause;
          level2Description = cause.causeDesc;
        } else if (cause.level === 3) {
          level1Id = String(cause.causeGlobal);
          level1Description = await this.getCauseDescription(level1Id);
          level2Id = cause.parentCause ?? '';
          level2Description = await this.getCauseDescription(level2Id);
          level3Id = cause.cause;
          level3Description = cause.causeDesc;
        } else {
          level1Id = cause.cause;
          level1Description = cause.causeDesc;
        }

        return new CauseHierarchy(
          level1Id,
          level1Description,
          level2Id,
          level2Description,
          level3Id,
          level3Description,
          cause.finalStatus,
          cause.family,
        );
      }),
    );
  }

  // Get All distinct cause description
  public async getAllDistinctCauseDesc(
    plant: number,
  ): Promise<Array<DownTimeCause>> {
    return this.downTimeCauseRepo
      .createQueryBuilder('down_time_cause')
      .select('DISTINCT down_time_cause.*')
      .where('down_time_cause.plant = :plant', { plant })
      .andWhere('down_time_cause.parent_cause IS NULL')
      .andWhere('down_time_cause.status = :status', { status: 'ACTIVATED' })
      .getRawMany();
  }

  public async getTranslationsByCause(
    plant: number,
    cause: string,
  ): Promise<
    Array<{
      plant: number;
      cause: string;
      targetLanguage: string;
      translatedDesc: string | null;
      isManual: boolean;
      createdAt?: Date;
      updatedAt?: Date;
      sourceDesc: string | null;
    }>
  > {
    try {
      // Fetch translations for the cause in the plant
      const translations = await this.downTimeCauseTranslationRepo.find({
        where: { plant, cause },
      });

      // Fetch source cause description (fallback)
      const causeEntity = await this.downTimeCauseRepo.findOne({
        where: { plant, cause },
        select: ['causeDesc'],
      });
      const sourceDesc = causeEntity ? causeEntity.causeDesc : null;

      return translations.map((t) => ({
        cause: t.cause,
        createdAt: t.createdAt,
        isManual: !!t.isManual,
        plant: t.plant,
        sourceDesc,
        targetLanguage: t.targetLanguage,
        translatedDesc: t.translatedDesc ?? null,
        updatedAt: t.updatedAt,
      }));
    } catch (error) {
      this.logger.error(
        `Failed to retrieve translations for plant ${plant} cause ${cause}: ${error}`,
      );
      throw new InternalServerErrorException('Failed to retrieve translations');
    }
  }

  /**
   * Return all translations for a given plant grouped by language and as flat entries.
   * The `languages` object is suitable to be directly written into i18n files where
   * the keys are of the form `down_time_cause.<cause>`.
   * @param plant - plant identifier
   * @returns Record where keys are language codes and values are key-value pairs of translations
   */
  public async getAllTranslationsByPlant(
    plant: number,
  ): Promise<Record<string, Record<string, string>>> {
    try {
      // Fetch all translations for the plant
      const translations = await this.downTimeCauseTranslationRepo.find({
        where: { plant },
      });

      // Fetch source descriptions for active causes in the plant only
      const causes = await this.downTimeCauseRepo.find({
        where: { plant, status: 'ACTIVATED' },
        select: ['cause', 'causeDesc'],
      });
      const sourceMap: Map<string, string> = new Map();
      const activeCauseSet: Set<string> = new Set();
      for (const c of causes) {
        sourceMap.set(c.cause, c.causeDesc ?? '');
        activeCauseSet.add(c.cause);
      }

      const languages: Record<string, Record<string, string>> = {};

      // Pre-filter translations to only include those for active causes
      const filteredTranslations = translations.filter((t) =>
        activeCauseSet.has(t.cause),
      );

      for (const t of filteredTranslations) {
        const lang = t.targetLanguage
          ? t.targetLanguage.toLowerCase()
          : 'unknown';
        const sourceDesc = sourceMap.get(t.cause) ?? '';
        // Use the original source description as the language key when available.
        // Fall back to a stable key when source description is empty.
        const key =
          sourceDesc && String(sourceDesc).trim() !== ''
            ? String(sourceDesc)
            : `down_time_cause.${t.cause}`;
        if (!languages[lang]) languages[lang] = {};
        languages[lang][key] = t.translatedDesc ?? sourceDesc ?? '';
      }

      return languages;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve all translations for plant ${plant}: ${error}`,
      );
      throw new InternalServerErrorException('Failed to retrieve translations');
    }
  }

  /**
   * Return all translations for a given plant as a flat array suitable for Excel export.
   * Each entry contains plant, cause, sourceDesc (original cause description),
   * targetLanguage, translatedDesc, isManual, createdAt and updatedAt.
   * @param plant - plant identifier
   * @returns Array of translation entries
   */
  public async getAllCausesTranslationsByPlant(plant: number): Promise<
    Array<{
      plant: number;
      cause: string;
      sourceDesc: string | null;
      targetLanguage: string | null;
      translatedDesc: string | null;
      isManual: boolean;
      createdAt?: Date;
      updatedAt?: Date;
    }>
  > {
    try {
      // Fetch all translations for the plant
      const translations = await this.downTimeCauseTranslationRepo.find({
        where: { plant },
      });

      // Fetch source descriptions for active causes in the plant only
      const causes = await this.downTimeCauseRepo.find({
        where: { plant, status: 'ACTIVATED' },
        select: ['cause', 'causeDesc'],
      });
      this.nestLogger.debug(
        `Found ${causes.length} active causes for plant ${plant}`,
      );
      const sourceMap: Map<string, string> = new Map();
      const activeCauseSet: Set<string> = new Set();
      for (const c of causes) {
        sourceMap.set(c.cause, c.causeDesc ?? '');
        activeCauseSet.add(c.cause);
      }

      // Build flat list, only include translations for active causes
      const result = translations
        .filter((t) => activeCauseSet.has(t.cause))
        .map((t) => ({
          cause: t.cause,
          createdAt: t.createdAt,
          isManual: !!t.isManual,
          plant: t.plant,
          sourceDesc: sourceMap.get(t.cause) ?? null,
          targetLanguage: t.targetLanguage ?? null,
          translatedDesc: t.translatedDesc ?? null,
          updatedAt: t.updatedAt,
        }));

      return result;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve all translations (flat) for plant ${plant}: ${error}`,
      );
      throw new InternalServerErrorException('Failed to retrieve translations');
    }
  }

  public async deleteTranslation(
    plant: number,
    cause: string,
    targetLanguage: string,
  ): Promise<void> {
    try {
      const response = await this.downTimeCauseTranslationRepo.delete({
        plant,
        cause,
        targetLanguage: targetLanguage.toLowerCase(),
      });

      if (response.affected === 0) {
        throw new NotFoundException(
          `Translation not found for plant ${plant}, cause ${cause}, language ${targetLanguage}`,
        );
      }
    } catch (error) {
      if (
        error instanceof NotFoundException ||
        error instanceof BadRequestException
      ) {
        throw error;
      }
      this.logger.error(
        `Failed to delete translation for plant ${plant} cause ${cause} language ${targetLanguage}: ${error}`,
      );
      throw new InternalServerErrorException('Failed to delete translation');
    }
  }
}

