/**
 * Safely convert a value to string without relying on default Object stringification.
 * Returns empty string for null/undefined.
 * @param value - Value to convert to string
 * @returns string
 */
export function safeToString(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean')
    return String(value);
  try {
    return JSON.stringify(value as Record<string, unknown>);
  } catch {
    return '';
  }
}

/**
 * Map a raw database row into a ResponseDownTimeCauseDTO
 * @param raw - Raw database row (key-value pairs) returned from queries; used to build the DTO
 * @returns ResponseDownTimeCauseDTO
 */
export function mapRawToResponseDTO(
  raw: Record<string, unknown>,
): ResponseDownTimeCauseDTO {
  const getFirst = (...keys: Array<string>): string => {
    for (const k of keys) {
      const v = raw[k];
      if (v !== undefined && v !== null) return safeToString(v);
    }
    return '';
  };

  const dto: ResponseDownTimeCauseDTO = {
    cause: getFirst('cause', 'down_time_cause_cause'),
    causeDesc: getFirst('cause desc', 'cause_desc', 'causeDesc') || undefined,
    causeGlobal: Number(
      getFirst('cause global', 'cause_global', 'causeGlobal') || 0,
    ),
    parentCause:
      getFirst('parent cause', 'parent_cause', 'parentCause') || undefined,
    plant: Number(raw['plant'] ?? raw['down_time_cause_plant'] ?? 0),
    status: getFirst('status') || '',
  } as ResponseDownTimeCauseDTO;

  return dto;
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { PlantConfig } from '../plant-config/entities/plant-config.entity';
import { DowntimeTicketJobOptionsDto } from './dto/down-time-ticket-job-options.dto';
import { DownTimeTicket } from './entities/down-time-ticket.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class DowntimeTicketCleanupService {
  private readonly logger = new AppLogger(DowntimeTicketCleanupService.name);

  public constructor(
    @InjectRepository(DownTimeTicket)
    private readonly downTimeTicketRepo: Repository<DownTimeTicket>,
    @InjectRepository(PlantConfig)
    private readonly plantConfigRepo: Repository<PlantConfig>,
  ) {}

  public async runDeleteDowntimeTicketProcedure(
    plantCode: number,
    options?: DowntimeTicketJobOptionsDto,
  ): Promise<void> {
    try {
      const parameters: [string | number] = [plantCode];
      const sqlParts: Array<string> = [
        'EXEC dbo.usp_cleanup_down_time_ticket_deleted_closed @PlantCode = @0',
      ];

      let parameterIndex = 1;

      if (options?.months !== undefined) {
        sqlParts.push(`@Months = @${parameterIndex}`);
        parameters.push(options.months);
        parameterIndex += 1;
      }

      if (options?.nbRowsToClean !== undefined) {
        sqlParts.push(`@NbRowsToClean = @${parameterIndex}`);
        parameters.push(options.nbRowsToClean);
        parameterIndex += 1;
      }

      if (options?.batchSize !== undefined) {
        sqlParts.push(`@BatchSize = @${parameterIndex}`);
        parameters.push(options.batchSize);
        parameterIndex += 1;
      }

      if (options?.delayMSBetweenRuns !== undefined) {
        sqlParts.push(`@DelayMSBetweenRuns = @${parameterIndex}`);
        parameters.push(options.delayMSBetweenRuns);
      }

      const sql = sqlParts.join(', ');

      await this.downTimeTicketRepo.query(sql, parameters);
    } catch (error) {
      this.logger.error(
        `Failed to execute dbo.usp_cleanup_down_time_ticket_deleted_closed for plant ${plantCode}: ${JSON.stringify(error)}`,
        error?.stack,
      );
      throw error;
    }
  }

  public async runDeleteDowntimeTicketProcedureForAllPlants(
    options?: DowntimeTicketJobOptionsDto,
  ): Promise<void> {
    try {
      // Fetch all plants from plant_config table
      const plantConfigs = await this.plantConfigRepo.find({
        select: ['plant'],
      });

      if (!plantConfigs || plantConfigs.length === 0) {
        this.logger.warn('No plants found in plant_config table');
        return;
      }

      this.logger.log(
        `Starting cleanup procedure for ${plantConfigs.length} plants`,
      );

      // Run cleanup sequentially for each plant
      for (const plantConfig of plantConfigs) {
        this.logger.log(
          `Running cleanup procedure for plant ${plantConfig.plant}`,
        );
        await this.runDeleteDowntimeTicketProcedure(plantConfig.plant, options);
        this.logger.log(
          `Cleanup procedure completed for plant ${plantConfig.plant}`,
        );
      }

      this.logger.log('Cleanup procedure completed for all plants');
    } catch (error) {
      this.logger.error(
        `Failed to execute cleanup procedure for all plants: ${JSON.stringify(error)}`,
        error?.stack,
      );
      throw error;
    }
  }
}

