  public constructor(
    // Inject the repository for DownTimeTicket entity
    @InjectRepository(DownTimeTicket)
    private readonly downTimeTicketRepo: Repository<DownTimeTicket>,
  ) {}

  public async create(downTimeTicket: CreateDownTimeTicketDto): Promise<void> {
    await this.downTimeTicketRepo.insert(downTimeTicket);
  }

  public findAll(): Promise<Array<DownTimeTicket>> {
    return this.downTimeTicketRepo.find();
  }

  public async findTicketsByResource(
    downTimeTicket: DownTimeTicketParameterDto,
  ): Promise<Array<ResponseDownTimeTicketDTO>> {
    try {
      const {
        plant,
        resource,
        cause,
        tool,
        shiftCode,
        status,
        startDate,
        endDate,
        ticketId,
        isFromMii,
      } = downTimeTicket;

      const formatStatus = (
        ticketStatus: Array<string> | undefined,
      ): Array<string> | undefined => {
        if (!ticketStatus || ticketStatus.length === 0) return undefined;

        return ticketStatus.map((item) => {
          switch (item.toLowerCase()) {
            case 'active': {
              return 'ACTI';
            }
            case 'closed': {
              return 'CLSD';
            }
            case 'deleted': {
              return 'DELT';
            }
            default: {
              return item;
            } // In case it's already formatted or a different status
          }
        });
      };

      const formattedStatus = formatStatus(status);
      // Format dates for SQL query

      const prior =
        "CASE WHEN (down_time_ticket.status = 'ACTI' AND down_time_ticket.cause = 6) THEN 1 ELSE (CASE WHEN (down_time_ticket.status = 'ACTI' AND down_time_ticket.cause != 6) THEN 2 ELSE (CASE WHEN down_time_ticket.STATUS = 'CLSD' THEN 3 ELSE (CASE WHEN down_time_ticket.STATUS = 'DELT' THEN 4 ELSE 0 END) END) END) END";
      const queryBuilder = this.downTimeTicketRepo
        .createQueryBuilder('down_time_ticket')
        .select('down_time_ticket.ticket', 'ticket')
        .addSelect('down_time_ticket.plant', 'plant')
        .addSelect('down_time_ticket.status', 'status')
        .addSelect('down_time_ticket.start_date', 'startDate')
        .addSelect('down_time_ticket.end_date', 'endDate')
        .addSelect('down_time_ticket.cause', 'cause')
        .addSelect('down_time_ticket.cause1', 'cause1')
        .addSelect('down_time_ticket.cause2', 'cause2')
        .addSelect('down_time_ticket.shift_code', 'shiftCode')
        .addSelect('down_time_ticket.duration', 'duration')
        .addSelect('down_time_ticket.remark', 'remark')
        .addSelect('down_time_cause.causeDesc', 'causeDesc')
        .addSelect('down_time_ticket.co_target', 'coTarget')
        .addSelect('down_time_ticket.tool', 'tool')
        .addSelect('down_time_cause_1.causeDesc', 'causeDesc1')
        .addSelect('down_time_cause_2.causeDesc', 'causeDesc2')
        .addSelect('down_time_ticket.modified_by', 'modifiedBy')
        .addSelect('down_time_ticket.mode', 'mode')
        .addSelect('down_time_ticket.lock_status', 'lockStatus')
        .addSelect(
          'down_time_ticket.last_processed_timestamp',
          'lastProcessedTimestamp',
        )
        .addSelect('down_time_ticket.userId', 'userId')
        .addSelect('down_time_ticket.planned_stoppage_id', 'plannedStoppageId')
        .addSelect('down_time_ticket.co_type', 'coType')
        .addSelect('down_time_ticket.tool_to', 'toolTo')
        .addSelect('down_time_ticket.master_ticket', 'masterTicket')
        .addSelect('down_time_ticket.co_master_ticket', 'coMasterTicket')
        .addSelect('down_time_ticket.resource', 'resource')
        .addSelect('down_time_ticket.modified_timestamp', 'modifiedTimestamp')
        .addSelect('down_time_ticket.created_on', 'createdOn')
        .leftJoin(
          DownTimeCause,
          'down_time_cause',
          'down_time_cause.plant = down_time_ticket.plant and down_time_cause.cause = cast(down_time_ticket.cause as VARCHAR)',
        )
        .leftJoin(
          DownTimeCause,
          'down_time_cause_1',
          'down_time_cause_1.plant = down_time_ticket.plant and down_time_cause_1.cause = cast(down_time_ticket.cause_1 as VARCHAR)',
        )
        .leftJoin(
          DownTimeCause,
          'down_time_cause_2',
          'down_time_cause_2.plant = down_time_ticket.plant and down_time_cause_2.cause = cast(down_time_ticket.cause_2 as VARCHAR)',
        )
        .where('down_time_ticket.plant = :plant', { plant })
        .andWhere('down_time_ticket.resource = :resource', { resource })
        .andWhere(
          new Brackets((qb) => {
            qb.where(
              "(down_time_ticket.status = 'ACTI' AND down_time_ticket.cause = 6)",
            )
              .orWhere(
                "(down_time_ticket.status = 'ACTI' AND down_time_ticket.cause != 6)",
              )
              .orWhere("down_time_ticket.status = 'CLSD'")
              .orWhere("down_time_ticket.status = 'DELT'");
          }),
        );
      if (ticketId !== undefined) {
        queryBuilder.andWhere('down_time_ticket.ticket =:ticketId', {
          ticketId,
        });
      }
      if (cause !== undefined) {
        const numericCause = cause.map(Number);
        queryBuilder.andWhere('down_time_ticket.cause IN (:...cause)', {
          cause: numericCause,
        });
      }
      if (formattedStatus !== undefined) {
        queryBuilder.andWhere('down_time_ticket.status IN (:...status)', {
          status: formattedStatus,
        });
      }
      if (tool !== undefined) {
        queryBuilder.andWhere('down_time_ticket.tool IN (:...tool)', {
          tool,
        });
      }
      if (shiftCode !== undefined) {
        const numericShiftCode = shiftCode.map(Number);
        queryBuilder.andWhere(
          'down_time_ticket.shift_code IN (:...shiftCode)',
          {
            shiftCode: numericShiftCode,
          },
        );
      }
      if (Number(isFromMii) === 1) {
        queryBuilder.andWhere('down_time_ticket.status <> :deletedStatus', {
          deletedStatus: 'DELT',
        });

        if (startDate && endDate) {
          queryBuilder.andWhere(
            new Brackets((qb) => {
              qb.where(
                '(down_time_ticket.start_date <= :startDateParam AND down_time_ticket.end_date > :startDateParam)',
                { startDateParam: startDate },
              )
                .orWhere(
                  '(:endDateParam > down_time_ticket.start_date AND down_time_ticket.start_date >= :startDateParam)',
                  { startDateParam: startDate, endDateParam: endDate },
                )
                .orWhere(
                  '(down_time_ticket.start_date <= :startDateParam AND down_time_ticket.end_date IS NULL)',
                  { startDateParam: startDate },
                );
            }),
          );
        }
      } else {
        if (startDate) {
          // Ajout d'un calcul pour la date de fin 24 heures après la startDate
          const endDateForStartDate = new Date(
            new Date(startDate).getTime() + 24 * 60 * 60 * 1000,
          );

          // Modification de la condition pour vérifier si la date est dans la plage de startDate à 24h après
          queryBuilder.andWhere(
            'down_time_ticket.start_date BETWEEN :startDate AND :endDateForStartDate',
            {
              endDateForStartDate,
              startDate,
            },
          );
        }

        if (endDate) {
          // Ajout d'un calcul pour la date de fin 24 heures après la startDate
          const endDateForendDate = new Date(
            new Date(endDate).getTime() + 24 * 60 * 60 * 1000,
          );

          // Modification de la condition pour vérifier si la date est dans la plage de startDate à 24h après
          queryBuilder.andWhere(
            'down_time_ticket.start_date BETWEEN :endDate AND :endDateForendDate',
            {
              endDate,
              endDateForendDate,
            },
          );
        }
      }
      const tickets = await queryBuilder
        .orderBy(prior)
        .addOrderBy('down_time_ticket.start_date', 'DESC')
        .getRawMany();

      if (tickets) {
        return tickets;
      }
      return [];
    } catch (error) {
      this.logger.error(error);
      return [];
    }
  }

