  public async getCommentsPerHour(
    plant: number,
    resource: string,
    from: Date,
    to: Date,
  ): Promise<Array<CommentsPerHour>> {
    try {
      const hours: Array<HourRange> = splitIntoHours(from, to);

      const results: Array<CommentsPerHour> = await Promise.all(
        hours.map(async ({ start, end }) => {
          const hourStart = start;
          const hourEnd = end;
          const hour = hourStart.getUTCHours();

          const tickets = await this.downTimeTicketRepo
            .createQueryBuilder('down_time_ticket')
            .select([
              'down_time_ticket.ticket',
              'down_time_ticket.cause',
              'down_time_ticket.cause1',
              'down_time_ticket.remark',
            ])
            .where('down_time_ticket.plant = :plant', { plant })
            .andWhere('down_time_ticket.resource = :resource', { resource })
            .andWhere('down_time_ticket.start_date >= :hourStart', {
              hourStart: hourStart.toISOString(),
            })
            .andWhere('down_time_ticket.start_date < :hourEnd', {
              hourEnd: hourEnd.toISOString(),
            })
            .andWhere('down_time_ticket.status != :status', { status: 'DELT' })
            .andWhere('down_time_ticket.non_quality_flag = :flag', { flag: 0 })
            .getRawMany();
          const validTickets = tickets.filter((ticket) => {
            const cause = ticket.down_time_ticket_cause;
            const cause1 = ticket.down_time_ticket_cause_1;
            const remark = ticket.down_time_ticket_remark;
            const isEmptyRemark =
              remark == null || String(remark).trim() === '';

            const isTargetCause =
              (cause === 5 && !cause1) ||
              (cause === 1 && !cause1) ||
              (cause === 4 && !cause1);

            return isTargetCause && isEmptyRemark;
          });
          const mappedTickets = validTickets.map((t) => ({
            ticket: t.down_time_ticket_ticket,
            cause: t.down_time_ticket_cause,
          }));
          return {
            comments: validTickets.length,
            hour: hour.toString().padStart(2, '0'),
            hourEnd,
            hourStart,
            tickets: mappedTickets,
          };
        }),
      );

      return results;
    } catch {
      return [];
    }
  }

  /**
   * Find active downtime tickets with cause = 6 and status = 'ACTI' within a provided date interval.
   * @param plant - The plant number
   * @param resource - The resource identifier
   * @param startDate - Interval start (inclusive)
   * @param endDate - Interval end (exclusive)
   * @returns Array of active cause 6 downtime tickets in the interval
   */
  public async findActiveCause6Tickets(
    plant: number,
    resource: string,
    startDate: Date,
    endDate: Date,
  ): Promise<Array<DownTimeTicket>> {
    try {
      const queryBuilder = this.downTimeTicketRepo
        .createQueryBuilder('down_time_ticket')
        .where('down_time_ticket.plant = :plant', { plant })
        .andWhere('down_time_ticket.resource = :resource', { resource })
        .andWhere('down_time_ticket.cause = :cause', { cause: 6 })
        .andWhere('down_time_ticket.status = :status', { status: 'ACTI' })
        .andWhere(
          '((down_time_ticket.start_date >= :startDate AND down_time_ticket.start_date < :endDate)' +
            ' OR (down_time_ticket.end_date IS NULL OR down_time_ticket.end_date > :startDate))',
          { startDate, endDate },
        )
        .orderBy('down_time_ticket.start_date', 'DESC');
      // Fetch raw results then explicitly check existence
      const rows = await queryBuilder.getRawMany();
      if (rows && rows.length > 0) {
        // Cast raw rows to expected return type; callers expect an array (empty when none)
        return rows as Array<DownTimeTicket>;
      }
      return [];
    } catch (error) {
      this.logger.error(
        `Error finding active cause 6 tickets: ${error.message}`,
      );
      return [];
    }
  }

  /**
   * Find active downtime tickets with cause = 6 and status = 'ACTI' within a provided date interval.
   * @param plant - The plant number
   * @param resource - The resource identifier
   * @param startDate - Interval start (inclusive)
   * @param threshold - threshold for duration
   * @returns Array of active cause 6 downtime tickets in the interval
   */
  public async findActiveTicketsForJIT(
    plant: number,
    resource: string,
    startDate: Date,
    threshold: number,
  ): Promise<Array<DownTimeTicket>> {
    try {
      const queryBuilder = this.downTimeTicketRepo
        .createQueryBuilder('down_time_ticket')
        .where('down_time_ticket.plant = :plant', { plant })
        .andWhere('down_time_ticket.resource = :resource', { resource })
        .andWhere('down_time_ticket.user_id IN (:...users)', {
          users: ['TAG', 'API_NTRS'],
        })
        .andWhere('down_time_ticket.status = :status', { status: 'ACTI' })
        .andWhere(
          `
        (
          (down_time_ticket.duration IS NOT NULL AND down_time_ticket.duration > :threshold)
          OR
          (down_time_ticket.duration IS NULL AND
           DATEDIFF(SECOND, down_time_ticket.start_date, GETDATE()) > :threshold
          )
        )
        `,
          { threshold },
        )

        .andWhere('down_time_ticket.start_date >= :startDate', { startDate })
        .orderBy('down_time_ticket.start_date', 'DESC');
      // Fetch raw results then explicitly check existence
      const rows = await queryBuilder.getRawMany();

      if (rows && rows.length > 0) {
        // Cast raw rows to expected return type; callers expect an array (empty when none)
        return rows as Array<DownTimeTicket>;
      }
      return [];
    } catch (error) {
      this.logger.error(
        `Error finding active cause 6 tickets: ${error.message}`,
      );
      return [];
    }
  }

  /**
   * Find the next planned stoppage ticket (cause=2, planned_stoppage_id!=0) within a shift interval, starting in the future.
   * @param plant Plant identifier
   * @param resource Resource identifier
   * @param startShift Shift start (inclusive)
   * @param endShift Shift end (exclusive)
   * @returns The next planned stoppage ticket or null if none found
   */
  public async findNextPlannedStoppage(
    plant: number,
    resource: string,
    startShift: Date,
    endShift: Date,
  ): Promise<DownTimeTicket | null> {
    try {
      const now = new Date();
      const ticket = await this.downTimeTicketRepo
        .createQueryBuilder('down_time_ticket')
        .where('down_time_ticket.plant = :plant', { plant })
        .andWhere('down_time_ticket.resource = :resource', { resource })
        .andWhere('down_time_ticket.cause = :cause', { cause: 2 })
        .andWhere('down_time_ticket.planned_stoppage_id != 0')
        .andWhere('down_time_ticket.start_date >= :startShift', { startShift })
        .andWhere('down_time_ticket.start_date < :endShift', { endShift })
        .andWhere('down_time_ticket.start_date > :now', { now })
        .orderBy('down_time_ticket.start_date', 'ASC')
        .getOne();
      return ticket || null;
    } catch (error) {
      this.logger.error(
        `Error finding next planned stoppage: ${error.message}`,
      );
      return null;
    }
  }

  /**
   * Retrieves downtime history for Event Center within the provided shift interval,
   * grouped by each hourly bucket and sorted latest-hour-first, tickets DESC within each slot.
   * @param plant - Plant identifier
   * @param resource - Resource identifier
   * @param shiftStart - Shift interval start (inclusive)
   * @param shiftEnd - Shift interval end (exclusive)
   * @returns Tickets grouped by hour slot, most recent hour first
   */
  public async findEventCenterDowntimeTicketHistory(
    plant: number,
    resource: string,
    shiftStart: Date,
    shiftEnd: Date,
  ): Promise<Array<EventCenterHourGroupDto>> {
    try {
      // Single DB query for all shift tickets, DESC so each hourly slice is already ordered.
      const raw: Array<EventCenterTicketDto> = await this.downTimeTicketRepo
        .createQueryBuilder('down_time_ticket')
        .select('down_time_ticket.ticket', 'ticket')
        .addSelect('down_time_ticket.plant', 'plant')
        .addSelect('down_time_ticket.status', 'status')
        .addSelect('down_time_ticket.start_date', 'startDate')
        .addSelect('down_time_ticket.end_date', 'endDate')
        .addSelect('down_time_ticket.cause', 'cause')
        .addSelect('down_time_ticket.cause1', 'cause1')
        .addSelect('down_time_ticket.cause2', 'cause2')
        .addSelect('down_time_cause.causeDesc', 'causeDesc')
        .addSelect('down_time_cause_1.causeDesc', 'causeDesc1')
        .addSelect('down_time_cause_2.causeDesc', 'causeDesc2')
        .addSelect('down_time_ticket.shift_code', 'shiftCode')
        .addSelect('down_time_ticket.duration', 'duration')
        .addSelect('down_time_ticket.remark', 'remark')
        .addSelect('down_time_ticket.resource', 'resource')
        .leftJoin(
          DownTimeCause,
          'down_time_cause',
          'down_time_cause.plant = down_time_ticket.plant AND down_time_cause.cause = CAST(down_time_ticket.cause AS VARCHAR)',
        )
        .leftJoin(
          DownTimeCause,
          'down_time_cause_1',
          'down_time_cause_1.plant = down_time_ticket.plant AND down_time_cause_1.cause = CAST(down_time_ticket.cause_1 AS VARCHAR)',
        )
        .leftJoin(
          DownTimeCause,
          'down_time_cause_2',
          'down_time_cause_2.plant = down_time_ticket.plant AND down_time_cause_2.cause = CAST(down_time_ticket.cause_2 AS VARCHAR)',
        )
        .where('down_time_ticket.plant = :plant', { plant })
        .andWhere('down_time_ticket.resource = :resource', { resource })
        .andWhere('down_time_ticket.start_date >= :shiftStart', { shiftStart })
        .andWhere('down_time_ticket.start_date < :shiftEnd', { shiftEnd })
        .andWhere("down_time_ticket.status != 'DELT'")
        .andWhere('down_time_ticket.non_quality_flag = :flag', { flag: 0 })
        .orderBy('down_time_ticket.start_date', 'DESC')
        .getRawMany();

      // Split the shift into hourly buckets
      const hours: Array<HourRange> = splitIntoHours(shiftStart, shiftEnd);

      const grouped: Array<EventCenterHourGroupDto> = hours.map(
        ({ start, end }) => {
          const slotTickets = raw.filter((t) => {
            const sd = new Date(t.startDate);
            return sd >= start && sd <= end;
          });

          return {
            hour: start.getUTCHours().toString().padStart(2, '0'),
            hourEnd: end,
            hourStart: start,
            tickets: slotTickets,
          };
        },
      );

      return grouped;
    } catch (error) {
      this.logger.error(
        `Error finding event center history tickets: ${error.message}`,
      );
      return [];
    }
  }
}

