@ApiTags('Family')
@Controller('family')
export class FamilyController {
  private readonly logger = new AppLogger(FamilyService.name);

  public constructor(private readonly familyService: FamilyService) {}

  @ApiExcludeEndpoint()
  @Post('create')
  public async create(
    @Body() family: Family,
    @Res() response: Response,
  ): Promise<Response> {
    try {
      const result = await this.familyService.create(family);

      return response.json(result);
    } catch (error) {
      this.logger.error(`error in creating family${error}`);
      return response
        .status(HttpStatus.INTERNAL_SERVER_ERROR)
        .json({ message: 'Internal Server Error' });
    }
  }

  @ApiExcludeEndpoint()
  @Get('all')
  public findAll(): Promise<Array<Family>> {
    return this.familyService.findAll();
  }

  @ApiOperation({
    description:
      'This endpoint allows you to check if a family exists, using the plant and family of resource parameters',
    summary: 'Get family by plant and by family resource',
  })
  @ApiOkResponse({
    description: 'FamilyList ',
    type: ResponseFamilyDTO,
  })
  @ApiNotFoundResponse({
    description: 'Family list Not Found.',
    status: 404,
  })
  @ApiInternalServerErrorResponse({
    description: 'Internal Server Error.',
    status: 500,
  })
  @Get('checkFamilyExistence')
  public async getFamilyExistence(
    @Query() query: FamilyParametersDTO,
    @Res() response: Response,
  ): Promise<Response> {
    const { plant, family } = query;
    const result = await this.familyService.checkFamilyExistence(plant, family);
    if (result !== undefined) {
      return response.json(result);
    }
    return response
      .status(HttpStatus.NOT_FOUND)
      .json({ message: 'Family list Not Found', status: HttpStatus.NOT_FOUND });
  }
}

