import { Family } from './entities/family.entity';
import { AppLogger } from '@/common/logger/app-logger';

@Injectable()
export class FamilyService {
  private readonly logger = new AppLogger(FamilyService.name);

  public constructor(
    // Inject the repository for Family entity
    @InjectRepository(Family)
    private readonly familyRepo: Repository<Family>,
  ) {}

  public async create(family: Family): Promise<void> {
    await this.familyRepo.insert(family);
  }

  public findAll(): Promise<Array<Family>> {
    return this.familyRepo.find();
  }

  public async checkFamilyExistence(
    plant: number,
    family: string,
  ): Promise<Array<ResponseFamilyDTO>> {
    try {
      const families = await this.familyRepo
        .createQueryBuilder('family')
        .select('family.family', 'family')
        .where('family.plant =:plant', { plant })
        .andWhere('family.family =:family', { family })
        .andWhere('family.activated =:activated', { activated: 1 })
        .getRawMany();
      if (family) {
        return families;
      }
      return [];
    } catch (error) {
      this.logger.error(error);
      return [];
    }
  }
}

