@Controller('probes')
export class ProbesController {
  private readonly healthMessage = 'mesx/order-api [OK]';

  private readonly logger: AppLogger = new AppLogger(ProbesController.name);

  public constructor(private readonly databaseChecker: MssqlDatabaseChecker) {}

  @Get('health')
  public getHello(): string {
    return this.healthMessage;
  }

  @Get('startup')
  public async isApplicationStartedUp(): Promise<string> {
    const isPendingMigrations = await this.databaseChecker.pendingMigrations();

    if (isPendingMigrations) {
      this.logger.log('Startup Probe: Migrations are still pending');
